"<!DOCTYPE html>
<html><head><meta name=\"viewport\" content=\"width=device-width,initial-scale=1,user-scalable=no\">
<style>
body{margin:0;background:#111;color:#fff;font-family:sans-serif;text-align:center;touch-action:none}
canvas{background:#2b2f4a;width:100%;max-width:800px;display:block;margin:auto}
.b{position:fixed;bottom:12px;width:70px;height:70px;border-radius:50%;background:#fff3;border:2px solid #fff;font-size:20px;color:#fff}
</style></head><body>
<canvas id=\"c\" width=\"800\" height=\"400\"></canvas>
<button class=\"b\" style=\"left:10px\" id=\"L\">◀</button>
<button class=\"b\" style=\"left:90px\" id=\"R\">▶</button>
<button class=\"b\" style=\"right:90px;background:#e335\" id=\"P\">👊</button>
<button class=\"b\" style=\"right:10px\" id=\"J\">⤒</button>
<script>
const c=document.getElementById('c'),x=c.getContext('2d');
const K={};
onkeydown=e=>K[e.key]=1;onkeyup=e=>K[e.key]=0;
[['L','a'],['R','d'],['J','w']].forEach(([id,k])=>{
 const b=document.getElementById(id);
 b.ontouchstart=e=>{e.preventDefault();K[k]=1};b.ontouchend=()=>K[k]=0;
});
document.getElementById('P').ontouchstart=e=>{e.preventDefault();punch()};
onkeypress=e=>{if(e.key==' '||e.key=='j')punch()};

let p,en,score,wave,over,t=0;
function reset(){p={x:100,y:300,vy:0,hp:100,face:1,atk:0,cd:0};en=[];score=0;wave=0;over=false;}
function spawn(){wave++;for(let i=0;i<wave+1;i++)en.push({x:850+i*90,y:300,hp:30+wave*5,face:-1,cd:0,sp:.7+Math.random()*.6+wave*.05,hit:0});}
function punch(){if(over){reset();return}if(p.cd>0)return;p.atk=10;p.cd=18;
 en.forEach(e=>{if(Math.abs(e.x-(p.x+p.face*35))<45@COMMENT_BODY@@COMMENT_BODY@Math.abs(e.y-p.y)<50){e.hp-=15;e.hit=8;e.x+=p.face*30;if(e.hp<=0)score+=10}});
 en=en.filter(e=>e.hp>0);}
function person(o,col){
 x.save();x.translate(o.x,o.y);
 x.fillStyle=o.hit>0?'#fff':col;x.fillRect(-15,-50,30,50); // gakuran uniform
 x.fillStyle='#f5cfa0';x.beginPath();x.arc(0,-62,13,0,7);x.fill(); // head
 x.fillStyle='#000';x.fillRect(-14,-76,28,8); // hair
 x.fillStyle='#f5cfa0';
 if(o.atk>0)x.fillRect(10*o.face,-42,35*o.face,10);
 x.restore();}
function loop(){
 t++;x.clearRect(0,0,800,400);
 x.fillStyle='#444';x.fillRect(0,305,800,95);
 if(!over){
  if(K.a||K.ArrowLeft){p.x-=4;p.face=-1}
  if(K.d||K.ArrowRight){p.x+=4;p.face=1}
  if((K.w||K.ArrowUp)@COMMENT_BODY@@COMMENT_BODY@p.y>=300)p.vy=-12;
  p.vy+=.6;p.y+=p.vy;if(p.y>300){p.y=300;p.vy=0}
  p.x=Math.max(20,Math.min(780,p.x));
  p.atk--;p.cd--;
  if(!en.length)spawn();
  en.forEach(e=>{
   e.hit--;e.cd--;
   e.face=p.x<e.x?-1:1;
   if(Math.abs(p.x-e.x)>40)e.x+=e.face*e.sp;
   else if(e.cd<=0){e.cd=60;e.atk=10;p.hp-=6+wave}
   e.atk--;
  });
  if(p.hp<=0)over=true;
 }
 person(p,'#1a1a2e');en.forEach(e=>person(e,'#8b1a1a'));
 x.fillStyle='#0008';x.fillRect(10,10,204,18);
 x.fillStyle='#e33';x.fillRect(12,12,Math.max(0,p.hp)*2,14);
 x.fillStyle='#fff';x.font='16px sans-serif';x.fillText('Score '+score+'  Wave '+wave,230,24);
 if(over){x.font='40px sans-serif';x.fillText('KO! Tap 👊 to retry',230,200)}
 requestAnimationFrame(loop);
}
reset();loop();
</script></body></html>

